<?php header('Content-Type: application/json');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit(json_encode(['error'=>'POST required']));}try{$c=require __DIR__.'/config.php';$d=json_decode(file_get_contents('php://input'),true);foreach(['name','phone','email','address','payment','items'] as $k)if(empty($d[$k]))throw new Exception("Missing $k");$p=new PDO("mysql:host={$c['db_host']};dbname={$c['db_name']};charset=utf8mb4",$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$total=0;foreach($d['items'] as $i)$total+=(float)$i['price']*(int)$i['qty'];$no='GD-'.date('YmdHis').'-'.random_int(100,999);$s=$p->prepare("INSERT INTO orders(order_no,customer_name,phone,email,address,payment_method,total,note,status) VALUES(?,?,?,?,?,?,?,?,?)");$s->execute([$no,$d['name'],$d['phone'],$d['email'],$d['address'],$d['payment'],$total,$d['note']??'','Pending']);$oid=$p->lastInsertId();$s=$p->prepare("INSERT INTO order_items(order_id,product_id,product_name,qty,price) VALUES(?,?,?,?,?)");foreach($d['items'] as $i)$s->execute([$oid,$i['id'],$i['name'],$i['qty'],$i['price']]);echo json_encode(['success'=>true,'order_id'=>$no]);}catch(Throwable $e){http_response_code(400);echo json_encode(['error'=>$e->getMessage()]);}